+/* The Paper view — a read-only reading/printing surface (PaperView/PaperBlock,
+   GramaireNotebookIsland.tsx): serif type, a narrow centered reading measure, and numbered
+   figures/captions for railroad diagrams, fully independent of the Livebook-style editing
+   affordances every other view has. */
+.gramaire__paper {
+  max-width: 42rem;
+  margin: 0 auto;
+  padding: 48px 24px 80px;
+  font-family: var(--font-serif);
+  font-size: 17px;
+  line-height: 1.75;
+  color: var(--fg);
+}
+.gramaire__paper h1,
+.gramaire__paper h2,
+.gramaire__paper h3,
+.gramaire__paper h4,
+.gramaire__paper h5,
+.gramaire__paper h6 {
+  font-family: var(--font-serif);
+  font-weight: 600;
+  line-height: 1.3;
+  margin: 1.6em 0 0.6em;
+}
+.gramaire__paper p {
+  margin: 0 0 1.1em;
+}
+.gramaire__paper table {
+  font-family: var(--font-ui);
+  font-size: 14px;
+  margin: 1.2em 0;
+}
+.gramaire__paper code {
+  font-family: var(--font-mono);
+  font-size: 0.9em;
+}
+
+/* A numbered figure — the one place Paper still shows a diagram, same railroad SVG source
+   (analysis.railroad[nonterminal]) every other view already renders, just captioned like a
+   real book figure instead of sitting bare beside a click-to-edit cell. */
+.gramaire__paper-figure {
+  margin: 2em 0;
+  padding: 0;
+}
+.gramaire__paper-figure > div {
+  display: flex;
+  justify-content: center;
+}
+.gramaire__paper-figure figcaption {
+  margin-top: 10px;
+  font-family: var(--font-ui);
+  font-size: 13px;
+  font-style: italic;
+  color: var(--fg-muted);
+  text-align: center;
+}
+
+/* Tokens/Settings/Precedence: no diagram to show, so a plain labeled source block — kept in the
+   monospace font even inside this serif reading view, matching ordinary book typesetting (prose
+   serif, code mono), not a special case invented for this feature. */
+.gramaire__paper-source {
+  margin: 2em 0;
+}
+.gramaire__paper-source-label {
+  font-family: var(--font-ui);
+  font-size: 12px;
+  font-weight: 600;
+  text-transform: uppercase;
+  letter-spacing: 0.04em;
+  color: var(--fg-muted);
+  margin-bottom: 6px;
+}
+.gramaire__paper-source pre {
+  margin: 0;
+  padding: 12px 16px;
+  border: 1px solid var(--border);
+  border-radius: 8px;
+  background: var(--bg-1);
+  font-family: var(--font-mono);
+  font-size: 13px;
+  line-height: 1.6;
+  color: var(--fg-secondary);
+  white-space: pre-wrap;
+  word-break: break-word;
+}

